nextflow_process {

    name "Test Process FASTAVALIDATOR"
    script "../main.nf"
    process "FASTAVALIDATOR"

    tag "modules"
    tag "modules_nfcore"
    tag "fastavalidator"

    test("deprecated") {

        when {
            process {
                """
                input[0] = [ [ id:'test' ], file('fasta') ]
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains("WARNING: This module has been deprecated.") }
            )
        }
    }
}
